(6713363, 1003843, 30982, '<td valign="top">Very effective shot for the challenge, though my personal preference would have been to leave the car in B&amp;W as well.</td>', 'Very effective shot for the challenge, though my personal preference would have been to leave the car in B&W as well.', '2012-03-16 22:27:21.000000', NULL, 1),
