(6715225, 1003209, 138253, '<td valign="top">"No photographers were harmed in the making of this image" i hope :)</td>', '"No photographers were harmed in the making of this image" i hope :)', '2012-03-18 13:58:29.000000', NULL, 1),
(6715226, 1004002, 138253, '<td valign="top">Interesting take on washing out the focal point of the image. Sadly many people do this far too often to these people in real life situations.<br/>I''m hoping you helped and didn''t just take their picture if this is genuine.</td>', 'Interesting take on washing out the focal point of the image. Sadly many people do this far too often to these people in real life situations.I''m hoping you helped and didn''t just take their picture if this is genuine.', '2012-03-18 13:58:37.000000', NULL, 1),
