(6715462, 1003878, 65234, '<td valign="top">My kind of solitude. Peacefully beautiful; love the color and tones.</td>', 'My kind of solitude. Peacefully beautiful; love the color and tones.', '2012-03-18 22:02:42.000000', NULL, 1),
(6715466, 1003928, 65234, '<td valign="top">Wonderfully moody, but open to interpretation.  Could be a million reasons for that beautifully backlit figure to be alone where he is.</td>', 'Wonderfully moody, but open to interpretation.  Could be a million reasons for that beautifully backlit figure to be alone where he is.', '2012-03-18 22:06:01.000000', NULL, 1),
(6715468, 1003933, 65234, '<td valign="top">A story well told.</td>', 'A story well told.', '2012-03-18 22:06:33.000000', NULL, 1),
(6715479, 1003933, 138630, '<td valign="top">A 10 from me.  That''s a lot of space between the door knob and the bed, but I see it as emphasizing the long time suggested in your title.  Excellent detail and expression/pose on the dog and the perspective is great.</td>', 'A 10 from me.  That''s a lot of space between the door knob and the bed, but I see it as emphasizing the long time suggested in your title.  Excellent detail and expression/pose on the dog and the perspective is great.', '2012-03-18 22:13:36.000000', NULL, 1),
(6715480, 1003861, 138630, '<td valign="top">A little dark but just because I am greedy and want to examine every detail -- otherwise the tones suit the mood here very well.  Excellent expression and I love the hanging stuffed animal.  10</td>', 'A little dark but just because I am greedy and want to examine every detail -- otherwise the tones suit the mood here very well.  Excellent expression and I love the hanging stuffed animal.  10', '2012-03-18 22:14:41.000000', NULL, 1),
(6715485, 1003806, 138630, '<td valign="top">I wish there was more color in the sky but I love everything else about this -- the tones, flowing lines and shapes of the sand, the unexpected concreteness of the structure, and of course the tiny camel and rider that bring a wonderful sense of scale to the image.  9</td>', 'I wish there was more color in the sky but I love everything else about this -- the tones, flowing lines and shapes of the sand, the unexpected concreteness of the structure, and of course the tiny camel and rider that bring a wonderful sense of scale to the image.  9', '2012-03-18 22:17:07.000000', NULL, 1),
(6715496, 1003928, 138630, '<td valign="top">One of my favorites of the challenge -- maybe my favorite.  I love the black and white, the ascent of the steps and leading lines of the rails and banisters, the light, the pose.  Perfect title - go Milne!  10</td>', 'One of my favorites of the challenge -- maybe my favorite.  I love the black and white, the ascent of the steps and leading lines of the rails and banisters, the light, the pose.  Perfect title - go Milne!  10', '2012-03-18 22:20:54.000000', NULL, 1),
(6715499, 1003969, 138630, '<td valign="top">Beautiful light, pose, tonal range.  This has a candid quality that I really like.  Wish you had the feet but since I''m thinking this may well have been "found" and taken quickly, that they are cut off is almost a plus rather than a minus.  A top pick for me.</td>', 'Beautiful light, pose, tonal range.  This has a candid quality that I really like.  Wish you had the feet but since I''m thinking this may well have been "found" and taken quickly, that they are cut off is almost a plus rather than a minus.  A top pick for me.', '2012-03-18 22:23:12.000000', NULL, 1),
(6715515, 1004030, 114285, '<td valign="top">This is really tremendous have so many thoughts going through my head viewing this...by the way you have a great side profile. Bump b/c I just love it.</td>', 'This is really tremendous have so many thoughts going through my head viewing this...by the way you have a great side profile. Bump b/c I just love it.', '2012-03-18 22:41:30.000000', NULL, 1),
