(6715649, 1003729, 142591, '<td valign="top">Came very close to the 6 at times but wasn''t to be.very happy though to smash my PB and finish in the top 50%!Thanks for the nice comments!</td>', 'Came very close to the 6 at times but wasn''t to be.very happy though to smash my PB and finish in the top 50%!Thanks for the nice comments!', '2012-03-19 00:24:26.000000', NULL, 0),
(6715653, 1003858, 113156, '<td valign="top">Oh that is good, well deserved bling.</td>', 'Oh that is good, well deserved bling.', '2012-03-19 00:26:07.000000', NULL, 0),
(6715655, 1003309, 138630, '<td valign="top">One of my 9''s -- obviously I thought this should have finished way higher :)  Beautiful woman, wonderful focus.  I found the alone in a crowd idea a nice take on this challenge.</td>', 'One of my 9''s -- obviously I thought this should have finished way higher :)  Beautiful woman, wonderful focus.  I found the alone in a crowd idea a nice take on this challenge.', '2012-03-19 00:26:26.000000', NULL, 0),
